<?php
/**
 * Icons everywhere: the built-in set (icon_paths() in core/render.php plus the ones below), the values an icon field stores, the
 * shared library of uploaded icons, and icon_picker(), the one icon field of every form (categories, menus, plugin settings).
 *
 * An icon value is one of: a built-in name ("book"), "emoji:🔥", an uploaded image under uploads/site ("site/icon_ab12.svg"),
 * "none" (an edit that removes an icon), or "" (no icon, or keep the item's own). icon_any() draws any of them.
 */

/** The built-in icons with what plugins add (filter icon.paths): name => SVG inner markup. Once per request. */
function icon_set(): array
{
    return request_cache('icon_paths', static fn(): array => (array)hook('icon.paths', icon_paths(), [])) ?? [];
}

/** Whether a value is one an icon field may store. */
function icon_value_ok(string $v): bool
{
    if ($v === '' || $v === 'none') return true;
    if (str_starts_with($v, 'emoji:')) { $e = substr($v, 6); return $e !== '' && mb_strlen($e) <= 8 && !preg_match('/[<>&"\'\s\/]/u', $e); }
    if (str_contains($v, '/')) { $path = explode('?', $v, 2)[0]; return (bool)preg_match('#^site/[a-z0-9_.-]+$#', $path) && is_file(UPLOAD_DIR . '/' . $path); }
    return isset(icon_set()[$v]);
}

/** The shared library of uploaded icons (uploads/site/icon_*), newest first: every icon field offers them under Your icons. */
function icon_library(): array
{
    $files = glob(UPLOAD_DIR . '/site/icon_*.*') ?: [];
    usort($files, static fn(string $a, string $b): int => (int)@filemtime($b) <=> (int)@filemtime($a));
    return array_map(static fn(string $f): string => 'site/' . basename($f), array_slice($files, 0, 200));
}

/** Add an uploaded icon to the library (named by its content, so the same file is kept once; an SVG is cleaned). Returns its value. */
function icon_library_add(array $file): string
{
    $hash = substr(sha1((string)@file_get_contents((string)($file['tmp_name'] ?? ''))), 0, 12);
    return explode('?', upload_site_image('icon_' . $hash, $file, ['png', 'jpg', 'gif', 'webp', 'svg'], 524288), 2)[0];
}

/**
 * The value an icon field posted: an uploaded file (field <name>_file) joins the library and wins, else the picked value when it is
 * valid, else $current. Throws RuntimeException with a message for the admin when the upload is refused.
 */
function icon_from_post(string $name, string $current = ''): string
{
    $file = upload_files_list($name . '_file')[0] ?? null;
    if ($file !== null) return icon_library_add($file);
    $v = trim(post_str($name, 200));
    return icon_value_ok($v) ? $v : $current;
}

/**
 * The icon field of every form: a button with the current icon that opens a panel with a search box, the built-in icons, Your
 * icons (the shared library), an emoji box and an upload (the form needs enctype="multipart/form-data"). Opts: keep => the label
 * of a first tile that keeps what the item has (value ""; "none" then removes the icon), none => false to leave out "No icon",
 * upload => false for no file input. app.js wires the tiles, the search and the emoji box ([data-icon-picker]).
 */
function icon_picker(string $name, string $value, array $opts = []): string
{
    $opts += ['keep' => '', 'none' => true, 'upload' => true];
    $keep = (string)$opts['keep'];
    $tile = static fn(string $v, string $inner, string $title, string $class = ''): string => '<button type="button" class="icon-pick' . $class . ($v === $value ? ' active' : '')
        . '" data-icon-pick="' . h($v) . '" data-name="' . h(strtolower($title)) . '" title="' . h($title) . '">' . $inner . '</button>';
    $now = $value === '' ? '<span class="icon-field-empty">' . h($keep !== '' ? $keep : t('No icon')) . '</span>' : ($value === 'none' ? '<span class="icon-field-empty">' . t('No icon') . '</span>' : icon_any($value));
    $html = '<details class="icon-field" data-icon-picker><summary><span class="icon-field-now">' . $now . '</span><span class="icon-field-label">' . t('Choose an icon') . '</span></summary>'
        . '<div class="icon-field-panel"><input type="hidden" name="' . h($name) . '" value="' . h($value) . '" data-icon-value>'
        . '<input type="search" class="icon-field-search" placeholder="' . h(t('Search icons')) . '" data-icon-search autocomplete="off"><div class="icon-field-grid">';
    if ($keep !== '') $html .= $tile('', h($keep), $keep, ' icon-pick-text');
    if ($opts['none']) $html .= $tile($keep !== '' ? 'none' : '', t('None'), t('No icon'), ' icon-pick-text');
    $mine = icon_library();
    if (str_contains($value, '/') && !in_array(explode('?', $value, 2)[0], $mine, true)) array_unshift($mine, $value); // a category's own older upload
    foreach ($mine as $v) $html .= $tile($v, icon_any($v), t('Your icons') . ' ' . basename(explode('?', $v, 2)[0]), ' icon-pick-mine');
    foreach (array_keys(icon_set()) as $n) if ($n !== 'grip') $html .= $tile((string)$n, icon((string)$n), (string)$n);
    $emoji = str_starts_with($value, 'emoji:') ? substr($value, 6) : '';
    return $html . '</div><div class="icon-field-extra"><label>' . t('Or an emoji') . ' <input type="text" class="icon-field-emoji" maxlength="8" value="' . h($emoji) . '" data-icon-emoji></label>'
        . ($opts['upload'] ? '<label>' . t('Or upload your own (PNG, WebP, JPG, GIF or SVG; it joins Your icons)') . ' <input type="file" name="' . h($name) . '_file" accept=".png,.jpg,.jpeg,.gif,.webp,.svg"></label>' : '')
        . '</div></div></details>';
}

